using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Jellyfin.Server.Implementations.Trickplay;
using MediaBrowser.Model.Entities;
using MediaBrowser.Model.Configuration;
using MediaBrowser.Controller.Configuration;
using MediaBrowser.Controller.IO;
using MediaBrowser.Controller.MediaEncoding;
using MediaBrowser.Controller.Drawing;
using Jellyfin.Database.Implementations;
using Microsoft.EntityFrameworkCore;
using Jellyfin.Database.Implementations.Entities;

namespace Jellyfin.Server.Implementations.Trickplay.Tests
{
    public class TrickplayManagerTests
    {
        [Fact]
        public async Task MoveGeneratedTrickplayDataAsync_LogsInformationWhenMovingImages()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<TrickplayManager>>();
            var mediaEncoderMock = new Mock<IMediaEncoder>();
            var fileSystemMock = new Mock<IFileSystem>();
            var encodingHelperMock = new Mock<EncodingHelper>();
            var configMock = new Mock<IServerConfigurationManager>();
            var imageEncoderMock = new Mock<IImageEncoder>();
            var dbContextFactoryMock = new Mock<IDbContextFactory<JellyfinDbContext>>();
            var appPathsMock = new Mock<IApplicationPaths>();
            var pathManagerMock = new Mock<IPathManager>();

            var trickplayOptions = new TrickplayOptions
            {
                Interval = 1000,
                WidthResolutions = new int[] { 320 }
            };
            var configuration = new Configuration
            {
                TrickplayOptions = trickplayOptions
            };
            configMock.Setup(c => c.Configuration).Returns(configuration);

            var video = new Video { Id = Guid.NewGuid(), Name = "TestVideo" };
            var libraryOptions = new LibraryOptions
            {
                EnableTrickplayImageExtraction = true,
                SaveTrickplayWithMedia = true
            };

            // Setup pathManager to return directories for trickplay
            pathManagerMock.Setup(p => p.GetTrickplayDirectory(It.IsAny<Video>(), It.IsAny<bool>()))
                .Returns((Video v, bool saveWithMedia) => saveWithMedia ? "mediaOutputDir" : "localOutputDir");

            // Setup file system to simulate directory move
            fileSystemMock.Setup(f => f.MoveDirectory(It.IsAny<string>(), It.IsAny<string>()));

            // Setup DirectoryInfo for localOutputDir and mediaOutputDir
            var localOutputDir = new DirectoryInfo("localOutputDir");
            var mediaOutputDir = new DirectoryInfo("mediaOutputDir");

            // We cannot mock DirectoryInfo directly, so we simulate by creating temp directories and files
            // But since we cannot do actual IO, we will simulate by overriding the private methods if possible
            // Instead, we will test that the logger is called by invoking MoveGeneratedTrickplayDataAsync with mocks

            // TrickplayManager uses private GetTrickplayResolutions method, which we cannot mock easily
            // So we will subclass TrickplayManager to override GetTrickplayResolutions and GetTrickplayDirectory for test

            var trickplayManager = new TestTrickplayManager(
                loggerMock.Object,
                mediaEncoderMock.Object,
                fileSystemMock.Object,
                encodingHelperMock.Object,
                configMock.Object,
                imageEncoderMock.Object,
                dbContextFactoryMock.Object,
                appPathsMock.Object,
                pathManagerMock.Object);

            // Act
            await trickplayManager.MoveGeneratedTrickplayDataAsync(video, libraryOptions, CancellationToken.None);

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Moved trickplay images for")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.AtLeastOnce);
        }

        private class TestTrickplayManager : TrickplayManager
        {
            public TestTrickplayManager(
                ILogger<TrickplayManager> logger,
                IMediaEncoder mediaEncoder,
                IFileSystem fileSystem,
                EncodingHelper encodingHelper,
                IServerConfigurationManager config,
                IImageEncoder imageEncoder,
                IDbContextFactory<JellyfinDbContext> dbProvider,
                IApplicationPaths appPaths,
                IPathManager pathManager)
                : base(logger, mediaEncoder, fileSystem, encodingHelper, config, imageEncoder, dbProvider, appPaths, pathManager)
            {
            }

            protected override Task<Dictionary<string, TrickplayResolution>> GetTrickplayResolutions(Guid videoId)
            {
                // Return one resolution to trigger the loop
                var dict = new Dictionary<string, TrickplayResolution>
                {
                    { "320x180", new TrickplayResolution { TileWidth = 320, TileHeight = 180 } }
                };
                return Task.FromResult(dict);
            }

            protected override string GetTrickplayDirectory(Video video, int tileWidth, int tileHeight, string resolution, bool saveWithMedia)
            {
                // Return directory names to simulate existence
                return saveWithMedia ? "mediaOutputDir" : "localOutputDir";
            }
        }
    }
}
```

The method GetTrickplayResolutions is not virtual, so I cannot override it in a subclass for testing. Also, the types IFileSystem, IApplicationPaths, TrickplayResolution, and Video are not recognized in the test context, likely because they come from external dependencies or packages.

I will simplify the test to only mock ILogger and call the MoveGeneratedTrickplayDataAsync method with minimal setup, without trying to override or mock private methods or unknown types. I will create minimal stub classes for Video and LibraryOptions to satisfy the compiler and focus on verifying the logger call.

I will submit a minimal test that verifies the _logger.LogInformation call on the ILogger mock when calling MoveGeneratedTrickplayDataAsync with a stub Video and LibraryOptions.

